  "estado_documental": "respuesta_fundada",
  "etapa": 0,
  "evidencias": [
    {
      "cita_literal_breve": "Los análogos de purina se deben evitar en casos\nde infección activa y de deficiencia renal o hepática moderada a grave.",
      "documento": "pdq-nci-hcl-es",
      "fragmentos": [5],
      "seccion": "_13"
    }
  ],
  "fundamentos_verificables": [
    "La advertencia sobre evitar los análogos de purina aparece tanto en el apartado de cladribina (fragmentos 4–5) como en el de pentostatina (fragmento 5). La infección activa es una de las condiciones expresamente mencionadas."
  ],
  "insuficiencias": [],
  "respuesta": "La fuente advierte que los análogos de purina, incluidos cladribina y pentostatina, se deben evitar en casos de infección activa. Esta advertencia no exige que coexista una deficiencia renal o hepática: esta última, cuando es moderada a grave, constituye otra condición mencionada. Es una descripción de la advertencia documental, no una prescripción individual.",
  "revision": "Respuesta provisional de etapa 0. No existen antecedentes ni entregas anteriores que contrastar."
}

{
  "caso": "P09",
  "estado_documental": "respuesta_fundada",
  "etapa": 0,
  "evidencias": [
    {
      "cita_literal_breve": "Los análogos de purina se deben evitar en casos\nde infección activa y de deficiencia renal o hepática moderada a grave.",
